BLOB = ''
import pathlib,hashlib,json,zlib,base64
D=json.loads(zlib.decompress(base64.b64decode(BLOB)))
paths=list(pathlib.Path('/kaggle/input').rglob('nanda-voice.mp3'))
if len(paths)!=1: raise RuntimeError('Expected one master voice, found '+str(paths))
base=paths[0].parent
missing=[]; mismatch=[]
for rel,want in D.items():
 f=base/rel
 if not f.is_file(): missing.append(rel);continue
 h=hashlib.sha256()
 with f.open('rb') as inp:
  for chunk in iter(lambda:inp.read(1048576),b''):h.update(chunk)
 if h.hexdigest()!=want: mismatch.append(rel)
print('CLOUD_VERIFY total',len(D),'missing',len(missing),'mismatch',len(mismatch),flush=True)
report={'files':len(D),'missing':missing,'mismatch':mismatch,'base':str(base),'pass':not missing and not mismatch}
pathlib.Path('/kaggle/working/HOLD_BACKUP_VERIFY.json').write_text(json.dumps(report,indent=2))
if missing or mismatch:raise RuntimeError('Cloud verification failed')
